    // 头像目录: 仓库 resource/img(pkg/lib/index.js → ../../resource/img);构建产物与 src 同仓库布局,故同一 URL 常量适用
    var AVATAR_DIR = new URL('../../resource/img/', import.meta.url).pathname;
    var AVATAR_EXTS = ['.png', '.jpg', '.jpeg', '.webp', '.gif'];
